// Golden test of how ordinary villagers and animals are posed and drawn (the condition for the refactors of
// L3DAnim::SampleLocal's blendSampler = false default, villager::SetYAngle as the single
// copy of InitializeStep / InitStepsXZ, ecs::DrawnModel instead of the drawn matrices of RenderingSystem.cpp,
// CarriedProps.cpp and Renderer.cpp's foot shadows, ecs::DrawnBodyModel / ecs::DrawnPose (the SuperVillager's turned
// copy and cross-faded pose, which an ordinary villager never has). It runs the real per-frame path on a real villager
// (PersonCelticMaleA1 + P_WALK_MAN) and a real animal (AnimalCow1 + A_COW_WALK) of the game's AllMeshes.g3d /
// AllAnims.anm:
//   L3DAnim::SampleLocal (both loop modes) -> ecs::UpdateAnimations (graphics::ComputePose) -> ecs::BeginLivingTurn /
//   ecs::UpdateMobileDrawing on a sloped hand-made island (between turns, the yaw turning, the slope shear) ->
//   ecs::UpdateCarriedProps (the villager's drawn matrix * bone 15, one villager on foot, one in the physics)
// and records every float, bit for bit. The drawn matrices of RenderingSystem and of the foot shadows (no headless entry
// point) are the HEAD code frozen below (HeadDrawnModel, HeadFootModel); where ecs::DrawnModel, ecs::DrawnBodyModel,
// ecs::DrawnPose and villager::SetYAngle exist (after the patch) they must give the same bits as the frozen copies (the
// pose drawn: the very vector UpdateAnimations wrote). They are found without a macro: the fallbacks of golden_fallback
// are only reached by qualified lookup when the real function is not declared ([namespace.qual]), so this file
// compiles on both trees.
// Modes: OPENBLACK_GOLDEN_DUMP=1 prints the table (between the GOLDEN-BEGIN / GOLDEN-END markers, to paste over the
// ones below); otherwise every value is compared with k_Golden (empty:
// the test skips). The game root is $OPENBLACK_TEST_BW_ROOT, else $OPENBLACK_GAME_PATH, else the default install.

