// ---- the functions that exist only after the patch -------------------------------------------------------------
// Qualified lookup of openblack::ecs::DrawnModel / openblack::ecs::villager::SetYAngle finds the real declaration
// when there is one and looks through these using-directives only when there is none (HEAD).
namespace golden_fallback
{
struct Missing
{
};
template <typename... Args>
Missing DrawnModel(Args&&...)
{
	return {};
}
template <typename... Args>
Missing DrawnBodyModel(Args&&...)
{
	return {};
}
template <typename... Args>
Missing DrawnPose(Args&&...)
{
	return {};
}
template <typename... Args>
Missing SetYAngle(Args&&...)
{
	return {};
}
} // namespace golden_fallback

namespace openblack::ecs
{
using namespace ::golden_fallback;
}
namespace openblack::ecs::villager
{
using namespace ::golden_fallback;
}

using namespace openblack;
using namespace openblack::ecs::components;

